import type { UpAxis } from '../types';

export type Sample = {
  id: string;
  name: string;
  description: string;
  upAxis: UpAxis;
  module: number;
};

/** Bundled test models (generated by scripts/generate-samples.mjs). */
export const SAMPLES: Sample[] = [
  {
    id: 'room',
    name: 'Sala simulada',
    description: 'Nuvem de pontos binária com cor (Z para cima)',
    upAxis: 'z',
    module: require('../../assets/models/sample_room.ply'),
  },
  {
    id: 'torus',
    name: 'Toro',
    description: 'Malha ASCII com faces (Y para cima)',
    upAxis: 'y',
    module: require('../../assets/models/sample_torus.ply'),
  },
];

export const getSample = (id: string) => SAMPLES.find((s) => s.id === id);
